"""TART station configuration: loading, validation and identifier resolution.

Station coordinates are never hard-coded in the software. They are read from a
YAML or JSON station catalogue whose entries record the provenance of every
coordinate. Two catalogue flavours share one format (a top-level ``stations``
mapping) and one loader:

* ``config/stations_registry.yaml`` (the default): GENERATED by
  ``tart-stations-update`` from a frozen snapshot of the TART network registry,
  keyed by canonical TART identifier (e.g. ``mu-udm``), with a ``metadata``
  block recording the registry URL, retrieval time and snapshot SHA-256;
* ``config/stations.yaml``: the legacy hand-curated catalogue keyed by
  convenience names (e.g. ``mauritius``), still accepted via ``--station-file``.

Convenience aliases (``mauritius -> mu-udm``) are hand-maintained in
``config/station_aliases.yaml``. Network access lives in
:mod:`tart_gnss.registry`, never here.
"""

from __future__ import annotations

import json
import logging
import math
from dataclasses import asdict, dataclass
from importlib import resources
from pathlib import Path
from typing import Dict, Iterable, List, Mapping, Optional, Union

import yaml

logger = logging.getLogger(__name__)

#: Plausible geodetic-height range for a ground station (metres). Values
#: outside this range almost certainly indicate a units or data-entry error.
MIN_ALTITUDE_M = -500.0
MAX_ALTITUDE_M = 9000.0


class StationConfigError(ValueError):
    """Raised when the station configuration is missing, malformed or invalid."""


@dataclass(frozen=True)
class Station:
    """A ground station (TART telescope) at a fixed geodetic position.

    Parameters
    ----------
    id
        Short configuration identifier used on the command line
        (e.g. ``"mauritius"``).
    name
        Human-readable station name.
    latitude_deg
        WGS84 geodetic latitude in degrees, north positive, in [-90, 90].
    longitude_deg
        WGS84 longitude in degrees, east positive, in [-180, 180].
    altitude_m
        Height above the WGS84 ellipsoid in metres (as published by the
        source; the vertical datum of TART-published heights is undocumented).
    source
        Free-text provenance of the coordinates.
    tart_id
        TART telescope identifier (e.g. ``"mu-udm"``), if known.
    api_url
        TART REST API base URL, if known. (The configuration key
        ``tart_api`` is accepted as a legacy alias.)
    archive_name
        Prefix of the telescope in the TART visibility archive (used by
        Stage 2). ``None`` means the archive location is unknown.
    archive_verified
        ``True`` if ``archive_name`` was verified to exist in the archive,
        ``False`` if it was not (or not checked), ``None`` if the catalogue
        does not record it (legacy catalogues).
    archive_verified_utc
        UTC ISO-8601 time of the archive verification, if any.

    Raises
    ------
    StationConfigError
        If any coordinate is missing, non-finite or out of range.
    """

    id: str
    name: str
    latitude_deg: float
    longitude_deg: float
    altitude_m: float
    source: str
    tart_id: Optional[str] = None
    api_url: Optional[str] = None
    archive_name: Optional[str] = None
    archive_verified: Optional[bool] = None
    archive_verified_utc: Optional[str] = None

    def __post_init__(self) -> None:
        validate_coordinates(
            self.id, self.latitude_deg, self.longitude_deg, self.altitude_m
        )
        if not self.source or not str(self.source).strip():
            raise StationConfigError(
                f"Station '{self.id}': a 'source' recording the provenance of "
                "the coordinates is required."
            )

    def to_dict(self) -> Dict[str, object]:
        """Return the station as a plain JSON-serialisable dictionary."""
        return asdict(self)


def _as_float(station_id: str, field: str, value: object) -> float:
    if value is None:
        raise StationConfigError(
            f"Station '{station_id}': '{field}' is missing (null). Coordinates "
            "must come from an authoritative source and are never guessed."
        )
    if isinstance(value, bool):
        raise StationConfigError(f"Station '{station_id}': '{field}' must be a number.")
    try:
        number = float(value)
    except (TypeError, ValueError) as exc:
        raise StationConfigError(
            f"Station '{station_id}': '{field}'={value!r} is not a number."
        ) from exc
    if not math.isfinite(number):
        raise StationConfigError(f"Station '{station_id}': '{field}' must be finite.")
    return number


def validate_coordinates(
    station_id: str, latitude_deg: object, longitude_deg: object, altitude_m: object
) -> None:
    """Validate geodetic station coordinates.

    Parameters
    ----------
    station_id
        Identifier used in error messages.
    latitude_deg, longitude_deg
        Geodetic latitude in [-90, 90] deg and longitude in [-180, 180] deg.
    altitude_m
        Height in metres, within [MIN_ALTITUDE_M, MAX_ALTITUDE_M].

    Raises
    ------
    StationConfigError
        If a value is missing, non-numeric, non-finite or out of range.
    """
    lat = _as_float(station_id, "latitude_deg", latitude_deg)
    lon = _as_float(station_id, "longitude_deg", longitude_deg)
    alt = _as_float(station_id, "altitude_m", altitude_m)
    if not -90.0 <= lat <= 90.0:
        raise StationConfigError(
            f"Station '{station_id}': latitude {lat} deg is outside [-90, 90]."
        )
    if not -180.0 <= lon <= 180.0:
        raise StationConfigError(
            f"Station '{station_id}': longitude {lon} deg is outside [-180, 180]."
        )
    if not MIN_ALTITUDE_M <= alt <= MAX_ALTITUDE_M:
        raise StationConfigError(
            f"Station '{station_id}': altitude {alt} m is outside "
            f"[{MIN_ALTITUDE_M}, {MAX_ALTITUDE_M}]."
        )


def _packaged(name: str) -> Path:
    return Path(str(resources.files("tart_gnss").joinpath(f"config/{name}")))


def default_station_file() -> Path:
    """Return the default station catalogue: the packaged frozen registry snapshot.

    This file is generated by ``tart-stations-update`` and never fetched at
    run time, so Stage 1 needs no network access and is reproducible.
    """
    return _packaged("stations_registry.yaml")


def legacy_station_file() -> Path:
    """Return the legacy hand-curated catalogue (``config/stations.yaml``)."""
    return _packaged("stations.yaml")


def default_alias_file() -> Path:
    """Return the hand-maintained alias file bundled with the package."""
    return _packaged("station_aliases.yaml")


def _read_mapping(path: Path) -> object:
    text = path.read_text(encoding="utf-8")
    try:
        if path.suffix.lower() == ".json":
            return json.loads(text)
        return yaml.safe_load(text)
    except (json.JSONDecodeError, yaml.YAMLError) as exc:
        raise StationConfigError(f"Cannot parse {path}: {exc}") from exc


def load_aliases(path: Optional[Union[str, Path]] = None) -> Dict[str, str]:
    """Load convenience aliases mapping a friendly name to a canonical TART id.

    Parameters
    ----------
    path
        YAML/JSON file with a top-level ``aliases`` mapping. ``None`` selects
        the packaged :func:`default_alias_file`.

    Returns
    -------
    dict
        Alias -> canonical TART identifier (both as strings).

    Raises
    ------
    StationConfigError
        If the file is missing or malformed.
    """
    path = Path(path) if path is not None else default_alias_file()
    if not path.is_file():
        raise StationConfigError(f"Alias file not found: {path}")
    data = _read_mapping(path)
    if not isinstance(data, Mapping) or not isinstance(data.get("aliases"), Mapping):
        raise StationConfigError(f"{path} must contain an 'aliases' mapping")
    return {str(k): str(v) for k, v in data["aliases"].items()}


def load_catalogue_metadata(path: Optional[Union[str, Path]] = None) -> Optional[Dict[str, object]]:
    """Return the ``metadata`` block of a station catalogue, if it has one.

    Generated registry catalogues record ``source``, ``retrieved_utc`` and
    ``sha256`` (of the raw registry snapshot) here. Legacy hand-curated
    catalogues have no metadata block, and ``None`` is returned.

    Raises
    ------
    StationConfigError
        If the file is missing or cannot be parsed.
    """
    path = Path(path) if path is not None else default_station_file()
    if not path.is_file():
        raise StationConfigError(f"Station configuration file not found: {path}")
    data = _read_mapping(path)
    meta = data.get("metadata") if isinstance(data, Mapping) else None
    return dict(meta) if isinstance(meta, Mapping) else None


def parse_station_config(data: Mapping[str, object]) -> Dict[str, Station]:
    """Build validated :class:`Station` objects from a parsed configuration.

    Parameters
    ----------
    data
        Mapping with a top-level ``stations`` key whose value maps station
        identifiers to dictionaries with ``name``, ``latitude_deg``,
        ``longitude_deg``, ``altitude_m`` and ``source`` (plus optional
        ``tart_id``, ``api_url``, ``archive_name``, ``archive_verified`` and
        ``archive_verified_utc``). Other top-level keys (e.g. ``metadata``)
        are ignored here; see :func:`load_catalogue_metadata`.

    Returns
    -------
    dict
        Station identifier -> :class:`Station`.
    """
    if not isinstance(data, Mapping) or "stations" not in data:
        raise StationConfigError("Station configuration must contain a 'stations' mapping.")
    entries = data["stations"]
    if not isinstance(entries, Mapping) or not entries:
        raise StationConfigError("'stations' must be a non-empty mapping.")
    stations: Dict[str, Station] = {}
    for station_id, entry in entries.items():
        station_id = str(station_id)
        if not isinstance(entry, Mapping):
            raise StationConfigError(f"Station '{station_id}' must be a mapping.")
        stations[station_id] = Station(
            id=station_id,
            name=str(entry.get("name") or station_id),
            latitude_deg=_as_float(station_id, "latitude_deg", entry.get("latitude_deg")),
            longitude_deg=_as_float(station_id, "longitude_deg", entry.get("longitude_deg")),
            altitude_m=_as_float(station_id, "altitude_m", entry.get("altitude_m")),
            source=str(entry.get("source") or ""),
            tart_id=entry.get("tart_id"),
            api_url=entry.get("api_url") or entry.get("tart_api"),
            archive_name=entry.get("archive_name"),
            archive_verified=entry.get("archive_verified"),
            archive_verified_utc=entry.get("archive_verified_utc"),
        )
    return stations


def load_stations(path: Optional[Union[str, Path]] = None) -> Dict[str, Station]:
    """Load and validate a YAML or JSON station configuration file.

    Parameters
    ----------
    path
        Configuration file (``.yaml``/``.yml``/``.json``). ``None`` selects
        the configuration bundled with the package.

    Returns
    -------
    dict
        Station identifier -> validated :class:`Station`.
    """
    path = Path(path) if path is not None else default_station_file()
    if not path.is_file():
        raise StationConfigError(f"Station configuration file not found: {path}")
    stations = parse_station_config(_read_mapping(path))
    logger.debug("Loaded %d stations from %s", len(stations), path)
    return stations


def normalise_station_id(text: str) -> str:
    """Normalise an identifier for matching: case-folded, ``-`` == ``_``."""
    return text.strip().lower().replace("-", "_")


def resolve_stations(
    station_ids: Iterable[str],
    catalogue: Mapping[str, Station],
    aliases: Optional[Mapping[str, str]] = None,
) -> List[Station]:
    """Resolve station identifiers against a loaded catalogue.

    Each requested identifier is tried, in order, as:

    1. an exact catalogue station ID;
    2. a normalised station ID (case-insensitive, ``-`` == ``_``);
    3. a configured alias (``aliases``), whose target is then resolved by
       station ID or TART ID;
    4. a station's ``tart_id`` (normalised).

    So ``za-rhodes``, ``za_rhodes`` and ``south_africa`` all select the same
    station.

    Parameters
    ----------
    station_ids
        Requested identifiers, in the order they should be used.
    catalogue
        Output of :func:`load_stations`.
    aliases
        Optional alias -> canonical TART id mapping (:func:`load_aliases`).

    Returns
    -------
    list of Station
        Stations in the requested order.

    Raises
    ------
    StationConfigError
        For unknown or duplicated stations, or an alias whose target is not
        in the catalogue.
    """
    norm = normalise_station_id
    by_id: Dict[str, Station] = {}
    by_tart: Dict[str, Station] = {}
    for station in catalogue.values():
        by_id[norm(station.id)] = station
        if station.tart_id:
            by_tart.setdefault(norm(station.tart_id), station)
    alias_map = {norm(k): v for k, v in (aliases or {}).items()}

    def lookup(requested: str) -> Optional[Station]:
        if requested in catalogue:
            return catalogue[requested]
        key = norm(requested)
        if key in by_id:
            return by_id[key]
        if key in alias_map:
            target = norm(alias_map[key])
            station = by_id.get(target) or by_tart.get(target)
            if station is None:
                raise StationConfigError(
                    f"Alias '{requested}' points to '{alias_map[key]}', which is not in the station catalogue"
                )
            return station
        return by_tart.get(key)

    resolved: List[Station] = []
    for requested in station_ids:
        station = lookup(requested)
        if station is None:
            known = ", ".join(sorted(catalogue))
            alias_text = f"; aliases: {', '.join(sorted(aliases))}" if aliases else ""
            raise StationConfigError(
                f"Unknown station '{requested}'. Known stations: {known}{alias_text}"
            )
        if station in resolved:
            raise StationConfigError(f"Station '{requested}' was requested more than once.")
        resolved.append(station)
    return resolved
